\set ON_ERROR_STOP on
create or replace function pg_temp.assert_zero(value bigint,message text) returns void language plpgsql as $$begin if value<>0 then raise exception 'ASSERTION_FAILED: % (%)',message,value;end if;end$$;
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.tables b left join pg_class c on c.relname=b.table_name and c.relnamespace='public'::regnamespace and c.relkind in ('r','p') where c.oid is null),'rollback removed baseline tables');
select pg_temp.assert_zero((select count(*) from phase35_rehearsal.columns b left join information_schema.columns c on c.table_schema='public' and c.table_name=b.table_name and c.column_name=b.column_name where c.column_name is null or row(c.ordinal_position,c.data_type,c.udt_name,c.is_nullable,coalesce(c.column_default,'')) is distinct from row(b.ordinal_position,b.data_type,b.udt_name,b.is_nullable,coalesce(b.column_default,''))),'rollback changed baseline columns');
select pg_temp.assert_zero((select count(*) from pg_tables where schemaname='public' and tablename in ('role_permissions','user_permission_overrides','account_invitations','offers','offer_events','payment_events','ledger_entries','analytics_events','notifications')),'rollback left additive tables');
select pg_temp.assert_zero((select count(*) from information_schema.columns where table_schema='public' and ((table_name='profiles' and column_name in ('account_status','status_changed_at','status_changed_by')) or (table_name='artist_representations' and column_name in ('revoked_at','revoked_by','revocation_reason')))),'rollback left Phase 3 columns');
select (select count(*) from phase35_rehearsal.tables) baseline_tables,(select count(*) from pg_tables where schemaname='public') post_rollback_tables;
select 'phase35_rollback_preservation' test_suite,'PASS' result;
